<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,ProgressReviewDraft,SupportConcern,LearningTask};
use App\Support\{ReviewWorkspace as W,StaffDuties};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Tests\TestCase;
class ReviewWorkspaceTest extends TestCase
{
 use LazilyRefreshDatabase;
 private function f(string $role='tutor'):array{$u=User::factory()->create(['role'=>$role]);$a=Apprentice::factory()->create($role==='mentor'?['mentor_id'=>$u->id]:['tutor_id'=>$u->id]);return compact('u','a');}
 public function test_assigned_tutor_finds_draft_and_missing_preparation_labels():void{$f=$this->f();$d=ProgressReviewDraft::factory()->create(['apprentice_id'=>$f['a']->id,'author_id'=>$f['u']->id,'fields'=>['learning'=>'PRIVATE-DRAFT-46']]);$b=Apprentice::factory()->create();$this->actingAs($f['u'])->get('/review-preparation')->assertRedirect(route('reviews.index',['view'=>'preparation']));$this->get('/reviews?view=preparation')->assertOk()->assertSee($f['a']->reference)->assertDontSee($b->reference)->assertDontSee('PRIVATE-DRAFT-46')->assertSee('saved preparation item(s)');$p=W::position($f['u'],$f['a']);$this->assertSame($d->id,$p['draft_id']);$this->assertNotEmpty($p['pending']);}
 public function test_mentor_scope_does_not_expand_to_unassigned_apprentices():void{$f=$this->f('mentor');$other=Apprentice::factory()->create();$this->actingAs($f['u'])->get('/review-preparation')->assertRedirect(route('reviews.index',['view'=>'preparation']));$this->get('/reviews?view=preparation')->assertOk()->assertSee($f['a']->reference)->assertDontSee($other->reference);$this->get('/apprentices/'.$other->id.'/review-worksheet')->assertForbidden();}
 public function test_transferred_assignment_removes_worksheet_access():void{$f=$this->f();$f['a']->update(['tutor_id'=>null]);$this->actingAs($f['u'])->get('/apprentices/'.$f['a']->id.'/review-worksheet')->assertForbidden();}
 public function test_frozen_review_is_not_presented_as_an_editable_preparation_checklist():void{$f=$this->f();$d=ProgressReviewDraft::factory()->create(['apprentice_id'=>$f['a']->id,'author_id'=>$f['u']->id]);$d->forceFill(['state'=>'Ready for signatures'])->save();$p=W::position($f['u'],$f['a']);$this->assertNull($p['draft_id']);$this->assertSame('Ready for signatures',$p['state']);$this->assertFalse($p['ready']);}
 public function test_factual_worksheet_does_not_create_a_review_or_private_support_copy():void{$f=$this->f();SupportConcern::factory()->create(['apprentice_id'=>$f['a']->id,'initial_note'=>'PRIVATE-SUPPORT-WORKSHEET-46']);$this->actingAs($f['u'])->get('/apprentices/'.$f['a']->id.'/review-worksheet?from=2026-01-01&to=2026-11-15')->assertOk()->assertSee('Factual preparation only')->assertDontSee('PRIVATE-SUPPORT-WORKSHEET-46');$this->assertDatabaseCount('progress_review_drafts',0);$this->assertDatabaseCount('review_preparation_briefs',0);}
 public function test_notes_keep_unknown_outcomes_and_actual_meeting_separate():void{$f=$this->f();$sheet=W::worksheet($f['u'],$f['a'],'2026-01-01','2026-11-15');$this->assertFalse($sheet['actual_meeting_recorded']);$this->assertStringContainsString('No qualification records',$sheet['notes']['progressDiscussion']);$this->assertStringContainsString('no meeting',$sheet['notes']['summary']);$this->assertFalse($sheet['writes_performed']);}
 public function test_source_changes_create_a_different_factual_capture_without_overwriting_draft():void{$f=$this->f();$d=ProgressReviewDraft::factory()->create(['apprentice_id'=>$f['a']->id,'author_id'=>$f['u']->id,'fields'=>['summary'=>'Human saved words']]);$before=$d->fresh()->getAttributes();$one=W::worksheet($f['u'],$f['a'],'2026-01-01','2026-11-15');LearningTask::factory()->create(['apprentice_id'=>$f['a']->id]);$two=W::worksheet($f['u'],$f['a'],'2026-01-01','2026-11-15');$this->assertNotSame($one['source_hash'],$two['source_hash']);$this->assertSame($before,$d->fresh()->getAttributes());}
 public function test_worksheet_pdf_is_real_and_labelled_preparation_only():void{$f=$this->f();$r=$this->actingAs($f['u'])->get('/apprentices/'.$f['a']->id.'/review-worksheet.pdf?from=2026-01-01&to=2026-11-15');$r->assertOk()->assertHeader('Content-Type','application/pdf');$this->assertStringStartsWith('%PDF',$r->getContent());if(getenv('GTA_QA_WORKSHEET_OUTPUT')){file_put_contents(getenv('GTA_QA_WORKSHEET_OUTPUT'),$r->getContent());}$this->assertDatabaseCount('progress_review_drafts',0);}
 public function test_search_and_page_counts_apply_after_current_scope():void{$f=$this->f();Apprentice::factory()->count(21)->create(['tutor_id'=>$f['u']->id]);$outside=Apprentice::factory()->create();$this->actingAs($f['u'])->get('/review-preparation?page=2')->assertRedirect(route('reviews.index',['view'=>'preparation','page'=>2]));$this->get('/reviews?view=preparation&page=2')->assertOk()->assertViewHas('reviewRows',fn($p)=>$p->total()===22&&count($p->items())===2)->assertDontSee($outside->reference);}
 #[\PHPUnit\Framework\Attributes\TestWith(['apprentice'])]
 #[\PHPUnit\Framework\Attributes\TestWith(['employer'])]
 #[\PHPUnit\Framework\Attributes\TestWith(['careers_adviser'])]
 public function test_other_roles_do_not_gain_review_preparation_access(string $role):void{$f=$this->f($role);$this->actingAs($f['u'])->get('/review-preparation')->assertForbidden();$this->get('/apprentices/'.$f['a']->id.'/review-worksheet.pdf')->assertForbidden();}
 public function test_long_or_future_period_is_rejected():void{$f=$this->f();$this->actingAs($f['u'])->getJson('/apprentices/'.$f['a']->id.'/review-worksheet?from=2020-01-01&to=2026-11-15')->assertUnprocessable();$this->getJson('/apprentices/'.$f['a']->id.'/review-worksheet?from=2099-01-01&to=2099-02-01')->assertUnprocessable();}
}
